KL=0.9532; SR=22050
def pick_len(f_target,note_ref):
    ft=f_target/(KL*2**((note_ref-48)/12.0))
    best=None
    for L in range(64,513):
        e=abs(np.log2((SR/L)/ft))
        if best is None or e<best[1]: best=(L,e)
    return best[0],best[1]
